{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Data Science Salaries by Experience Level (2020-2022)",
  "data": {"url": "ds_salaries.csv"},
  "transform": [
    {
      "filter": "datum.work_year >= 2020 && datum.work_year <= 2022"
    },
    {
      "aggregate": [
        {"op": "mean", "field": "salary_in_usd", "as": "avg_salary"},
        {"op": "count", "as": "record_count"}
      ],
      "groupby": ["work_year", "experience_level"]
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "strokeWidth": 3,
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "work_year",
      "type": "ordinal",
      "title": "Year",
      "axis": {"labelAngle": 0}
    },
    "y": {
      "field": "avg_salary",
      "type": "quantitative",
      "title": "Average Salary (USD)",
      "scale": {"domain": [50000, 250000]}
    },
    "color": {
      "field": "experience_level",
      "type": "nominal",
      "title": "Experience Level",
      "scale": {
        "domain": ["EN", "MI", "SE", "EX"],
        "range": ["#4c78a8", "#54a24b", "#eeca3b", "#e45756"]
      },
      "legend": {
        "title": "Experience Level",
        "symbolSize": 100,
        "labelFontSize": 12,
        "titleFontSize": 14
      }
    },
    "tooltip": [
      {"field": "work_year", "title": "Year"},
      {"field": "experience_level", "title": "Level"},
      {"field": "avg_salary", "title": "Avg Salary", "format": "$,"},
      {"field": "record_count", "title": "Data Points"}
    ]
  },
  "config": {
    "view": {"stroke": "transparent"},
    "axis": {"labelFontSize": 12, "titleFontSize": 14},
    "legend": {"padding": 10}
  },
  "width": 600,
  "height": 400
}

